import { CdkTrapFocus } from '@angular/cdk/a11y';
import { Dialog, DialogConfig, DialogRef } from '@angular/cdk/dialog';
import { ComponentPortal, ComponentType } from '@angular/cdk/portal';
import { Overlay, OverlayRef } from '@angular/cdk/overlay';
import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  Injectable,
  booleanAttribute,
  inject,
  input,
  model,
  output,
} from '@angular/core';
import { CsButtonDirective } from '../core/foundations/cs-button.directive';
import { CsBreakpointService } from '../core/platform/cs-breakpoint.service';
import { CsLocalizationService } from '../core/platform/cs-localization.service';
import { DrawerMode } from './drawer-mode.type';
import { DrawerPosition } from './drawer-position.type';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'cs-drawer',
  imports: [CdkTrapFocus],
  templateUrl: './drawer.component.html',
  host: { '[class]': "'cs-drawer cs-drawer--'+position()" },
  styleUrl: './drawer.component.scss',
})
export class DrawerComponent {
  private readonly breakpoints = inject(CsBreakpointService);
  readonly opened = model(false);
  readonly position = input<DrawerPosition>('end');
  readonly mode = input<DrawerMode>('modal');
  readonly responsiveFullScreen = input(false, { transform: booleanAttribute });
  readonly dismissible = input(true, { transform: booleanAttribute });
  readonly size = input('24rem');
  readonly closed = output<void>();
  readonly resolvedMode = () =>
    this.responsiveFullScreen() && this.breakpoints.compact() ? 'modal' : this.mode();
  protected dismiss(): void {
    if (this.dismissible()) {
      this.opened.set(false);
      this.closed.emit();
    }
  }
}

html:
@if (opened()) {
  <section
    cdkTrapFocus
    [attr.role]="resolvedMode() === 'modal' ? 'dialog' : 'complementary'"
    [attr.aria-modal]="resolvedMode() === 'modal' ? 'true' : null"
  >
    <header><ng-content select="[csDrawerHeader]" /></header>
    <div class="content"><ng-content /></div>
    <footer><ng-content select="[csDrawerFooter]" /></footer>
  </section>
  @if (resolvedMode() === 'modal') {
    <button class="backdrop" aria-label="Close" (click)="dismiss()"></button>
  }
}

scss:
section {
  position: fixed;
  z-index: 70;
  inset-block: 0;
  inset-inline-end: 0;
  inline-size: min(24rem, 100vw);
  display: grid;
  grid-template-rows: auto 1fr auto;
  background: var(--cs-paper);
  box-shadow: var(--cs-shadow-lg);
}
.content {
  overflow: auto;
  padding: var(--cs-space-5);
}
header,
footer {
  padding: var(--cs-space-4);
}
.backdrop {
  position: fixed;
  z-index: 60;
  inset: 0;
  border: 0;
  background: #0008;
}
